def generate_uid(prefix: str = "ORD") -> str:
    ts = hex(int(time.time()))[2:].upper()
    rnd = "".join(random.choices(string.ascii_uppercase + string.digits, k=5))
    return f"{prefix}-{ts}-{rnd}"


