class UserGuardMiddleware(BaseMiddleware):
    """ظٹط³ط¬ظ‘ظ„ ط§ظ„ظ…ط³طھط®ط¯ظ… ظˆظٹط­ط¯ظ‘ط« ط¨ظٹط§ظ†ط§طھظ‡ ظˆظٹظ…ظ†ط¹ ط§ظ„ظ…ط­ط¸ظˆط±ظٹظ† ظپظٹ ط§ظ„ظ…ط­ط§ط¯ط«ط§طھ ط§ظ„ط®ط§طµط©."""

    async def __call__(self, handler, event, data):
        user = data.get("event_from_user")
        chat = data.get("event_chat")
        if user and not user.is_bot and chat and chat.type == "private":
            u = await WalletService.get_or_create_user(user.id, user.username or "", user.full_name or "")
            if u[4] == 1 and user.id != ADMIN_ID:
                try:
                    if isinstance(event, types.CallbackQuery):
                        await event.answer("â›” ط­ط³ط§ط¨ظƒ ظ…ط­ط¸ظˆط± ظ…ظ† ط§ط³طھط®ط¯ط§ظ… ط§ظ„ط¨ظˆطھ.", show_alert=True)
                    elif isinstance(event, types.Message):
                        await event.answer("â›” ط­ط³ط§ط¨ظƒ ظ…ط­ط¸ظˆط± ظ…ظ† ط§ط³طھط®ط¯ط§ظ… ط§ظ„ط¨ظˆطھ.")
                except Exception:
                    pass
                return None
        return await handler(event, data)


_sub_cache: Dict[int, float] = {}
_sub_warn_at = 0.0


async def check_subscription(user_id: int) -> bool:
    global _sub_warn_at
    ref = await force_channel_ref()
    if not ref:
        return True
    now = time.monotonic()
    if _sub_cache.get(user_id, 0) > now:
        return True
    try:
        m = await bot.get_chat_member(ref, user_id)
        ok = m.status in ("member", "administrator", "creator") or (m.status == "restricted" and getattr(m, "is_member", False))
    except Exception as e:
        # ظ„ط§ ظ†ظ‚ظپظ„ ط§ظ„ط¨ظˆطھ ط¹ظ„ظ‰ ط§ظ„ط¬ظ…ظٹط¹ ط¥ط°ط§ طھط¹ط°ط± ط§ظ„ظپط­طµ (ظ…ط«ظ„ط§ظ‹ ط§ظ„ط¨ظˆطھ ظ„ظٹط³ ظ…ط´ط±ظپط§ظ‹ ظپظٹ ط§ظ„ظ‚ظ†ط§ط©)
        log.error("subscription check failed: %s", e)
        if now - _sub_warn_at > 600:
            _sub_warn_at = now
            try:
                await bot.send_message(ADMIN_ID, "âڑ ï¸ڈ طھط¹ط°ط± ظپط­طµ ط§ظ„ط§ط´طھط±ط§ظƒ ط§ظ„ط¥ط¬ط¨ط§ط±ظٹ. طھط£ظƒط¯ ط£ظ† ط§ظ„ط¨ظˆطھ <b>ظ…ط´ط±ظپ</b> ظپظٹ ط§ظ„ظ‚ظ†ط§ط© ظˆط£ظ† ط§ظ„ظ…ط¹ط±ظپ طµط­ظٹط­. "
                                                 "طھظ… ط§ظ„ط³ظ…ط§ط­ ظ„ظ„ظ…ط³طھط®ط¯ظ…ظٹظ† ظ…ط¤ظ‚طھط§ظ‹.")
            except Exception:
                pass
        return True
    if ok:
        _sub_cache[user_id] = now + 120
    return ok


