_decl_alert_at: Dict[int, float] = {}


async def deposit_block_reason(uid: int) -> Optional[str]:
    """ط­ط¯ظˆط¯ ط§ظ„ط¥ط³ط§ط،ط©: ط¥ظٹط¯ط§ط¹ط§طھ ظ…ط¹ظ„ظ‚ط© ظƒط«ظٹط±ط©طŒ ط£ظˆ ط¹ط¯ط¯ ظٹظˆظ…ظٹ ظƒط¨ظٹط±طŒ ط£ظˆ ط±ظپط¶ ظ…طھظƒط±ط±."""
    r = await fetch_one(
        "SELECT COALESCE(SUM(status='UNDER_REVIEW'), 0) AS pend, "
        "COALESCE(SUM(created_at >= datetime('now', '-1 day')), 0) AS day_n, "
        "COALESCE(SUM(status='DECLINED' AND created_at >= datetime('now', '-1 day')), 0) AS dec_n "
        "FROM payments WHERE user_id=?", (uid,)
    )
    if r["dec_n"] >= MAX_DECLINED_24H:
        now = time.monotonic()
        if now - _decl_alert_at.get(uid, 0) > 6 * 3600:
            _decl_alert_at[uid] = now
            try:
                await bot.send_message(ADMIN_ID, f"ًںڑ¨ ط§ظ„ظ…ط³طھط®ط¯ظ… <code>{uid}</code> ظ„ط¯ظٹظ‡ {r['dec_n']} ط¥ظٹط¯ط§ط¹ط§طھ ظ…ط±ظپظˆط¶ط© ط®ظ„ط§ظ„ 24 ط³ط§ط¹ط©طŒ ظˆطھظ… ط¥ظٹظ‚ط§ظپ ط·ظ„ط¨ط§طھظ‡ ط§ظ„ط¬ط¯ظٹط¯ط© ظ…ط¤ظ‚طھط§ظ‹.")
            except Exception:
                pass
        return "â›” طھظ… ط¥ظٹظ‚ط§ظپ ط·ظ„ط¨ط§طھ ط§ظ„ط¥ظٹط¯ط§ط¹ ظ…ط¤ظ‚طھط§ظ‹ ط¨ط³ط¨ط¨ طھظƒط±ط§ط± ط§ظ„ط·ظ„ط¨ط§طھ ط§ظ„ظ…ط±ظپظˆط¶ط©. ظٹط±ط¬ظ‰ ط§ظ„طھظˆط§طµظ„ ظ…ط¹ ط§ظ„ط¯ط¹ظ… ط§ظ„ظپظ†ظٹ."
    if r["pend"] >= MAX_PENDING_DEPOSITS:
        return f"âڈ³ ظ„ط¯ظٹظƒ {r['pend']} ط·ظ„ط¨ط§طھ ط¥ظٹط¯ط§ط¹ ظ‚ظٹط¯ ط§ظ„ظ…ط±ط§ط¬ط¹ط©. ط§ظ†طھط¸ط± طھط£ظƒظٹط¯ظ‡ط§ ظ‚ط¨ظ„ ط¥ط±ط³ط§ظ„ ط·ظ„ط¨ ط¬ط¯ظٹط¯."
    if r["day_n"] >= MAX_DEPOSITS_PER_DAY:
        return "â›” ط¨ظ„ط؛طھ ط§ظ„ط­ط¯ ط§ظ„ط£ظ‚طµظ‰ ظ„ط·ظ„ط¨ط§طھ ط§ظ„ط¥ظٹط¯ط§ط¹ ط§ظ„ظٹظˆظ…. ط­ط§ظˆظ„ ط؛ط¯ط§ظ‹ ط£ظˆ طھظˆط§طµظ„ ظ…ط¹ ط§ظ„ط¯ط¹ظ…."
    return None


async def tx_exists(tx_code: str) -> bool:
    async with get_db() as db:
        cur = await db.execute("SELECT 1 FROM payments WHERE sham_tx_id = ?", (tx_code,))
        return await cur.fetchone() is not None


@dp.message(WalletFlow.tx_code)
async def wallet_tx_rec(message: types.Message, state: FSMContext):
    tx_code = re.sub(r"[\s\-_.,]", "", normalize_digits(txt(message)))
    if not tx_code.isdigit() or not (4 <= len(tx_code) <= 30):
        await message.reply("âڑ ï¸ڈ ط±ظ‚ظ… ط§ظ„ط¹ظ…ظ„ظٹط© ظٹط¬ط¨ ط£ظ† ظٹطھظƒظˆظ† ظ…ظ† ط£ط±ظ‚ط§ظ… ظپظ‚ط· (ظ…ظ† 4 ط¥ظ„ظ‰ 30 ط±ظ‚ظ…ط§ظ‹). ط£ط¹ط¯ ط¥ط±ط³ط§ظ„ظ‡:")
        return
    if await tx_exists(tx_code):
        await message.reply("â›” ط±ظ‚ظ… ط§ظ„ط¹ظ…ظ„ظٹط© ظ‡ط°ط§ ظ…ط³طھط®ط¯ظ… ظ…ط³ط¨ظ‚ط§ظ‹! ظٹط±ط¬ظ‰ ط¥ط¯ط®ط§ظ„ ط±ظ‚ظ… طµط­ظٹط­:")
        return
    await state.update_data(sham_tx=tx_code)
    await state.set_state(WalletFlow.amount)
    await message.answer(
        f"ًں’° ط§ظ„ط¢ظ† ط£ط±ط³ظ„ <b>ط§ظ„ظ…ط¨ظ„ط؛ ط§ظ„ظ…ط­ظˆظژظ‘ظ„</b> ط¨ط§ظ„ظ„ظٹط±ط© ط§ظ„ط³ظˆط±ظٹط© (ط£ظ‚ظ„ ظ…ط¨ظ„ط؛ {MIN_TOPUP:,} ظ„.ط³):",
        reply_markup=cancel_kb(),
    )


@dp.message(WalletFlow.amount)
async def wallet_amt_rec(message: types.Message, state: FSMContext):
    amt = to_int(txt(message))
    if amt is None or amt < MIN_TOPUP or amt > 1_000_000_000:
        await message.reply(f"âڑ ï¸ڈ ظٹط±ط¬ظ‰ ط¥ط¯ط®ط§ظ„ ظ…ط¨ظ„ط؛ طµط­ظٹط­ ط¨ط§ظ„ط£ط±ظ‚ط§ظ… (ط§ظ„ط­ط¯ ط§ظ„ط£ط¯ظ†ظ‰ {MIN_TOPUP:,} ظ„.ط³):")
        return
    data = await state.get_data()
    tx_code = data.get("sham_tx", "")
    if not tx_code:
        await state.clear()
        await message.answer("âڑ ï¸ڈ ط§ظ†طھظ‡طھ ط¬ظ„ط³ط© ط§ظ„ط´ط­ظ†طŒ ظٹط±ط¬ظ‰ ط§ظ„ط¨ط¯ط، ظ…ظ† ط¬ط¯ظٹط¯.", reply_markup=KB([[B("â‍• ط´ط­ظ† ط§ظ„ظ…ط­ظپط¸ط©", "wallet:topup")]]))
        return

    reason = await deposit_block_reason(message.from_user.id)
    if reason:
        await state.clear()
        await message.answer(reason, reply_markup=HOME_KB)
        return
    pay_id = generate_uid("PAY")
    try:
        async with get_db() as db:
            await db.execute(
                "INSERT INTO payments (payment_id, user_id, method, amount, sham_tx_id) VALUES (?, ?, 'SHAM_CASH', ?, ?)",
                (pay_id, message.from_user.id, amt, tx_code),
            )
    except aiosqlite.IntegrityError:
        await state.set_state(WalletFlow.tx_code)
        await message.reply("â›” ط±ظ‚ظ… ط§ظ„ط¹ظ…ظ„ظٹط© ظ‡ط°ط§ ظ…ط³طھط®ط¯ظ… ظ…ط³ط¨ظ‚ط§ظ‹! ط£ط±ط³ظ„ ط±ظ‚ظ… ط¹ظ…ظ„ظٹط© طµط­ظٹط­ط§ظ‹:")
        return

    text_to_group = (
        f"ًں’³ <b>ط·ظ„ط¨ ط¥ظٹط¯ط§ط¹ ط¬ط¯ظٹط¯ ظ‚ظٹط¯ ط§ظ„طھط¯ظ‚ظٹظ‚ ط§ظ„ظ…ط§ظ„ظٹ:</b>\n"
        f"ًں†” ط±ظ‚ظ… ط§ظ„ط¯ظپط¹ط©: <code>{pay_id}</code>\n"
        f"ًں‘¤ ط§ظ„ط²ط¨ظˆظ†: {user_tag(message.from_user)} (<code>{message.from_user.id}</code>)\n"
        f"ًں”‘ UID: <code>{message.from_user.id}</code>\n"
        f"ًں’° ط§ظ„ظ…ط¨ظ„ط؛ ط§ظ„ظ…ط­ظˆظژظ‘ظ„: <b>{amt:,} ظ„.ط³</b>\n"
        f"ًں§¾ ط±ظ‚ظ… ط§ظ„ط¹ظ…ظ„ظٹط©: <code>{esc(tx_code)}</code>\n"
    )
    kb = KB([[B("âœ… طھط£ظƒظٹط¯ ظˆط¥ظٹط¯ط§ط¹", f"adm_pay:ok:{pay_id}"), B("â‌Œ ط±ظپط¶", f"adm_pay:no:{pay_id}")]])
    await send_to_staff(DEPOSIT_ADMIN_GROUP, text_to_group, kb)
    await state.clear()
    await message.answer(
        "âœ… طھظ… ط¥ط±ط³ط§ظ„ ط·ظ„ط¨ ط§ظ„ط¥ظٹط¯ط§ط¹ ظ„ظ„ط¥ط¯ط§ط±ط©طŒ ظˆط³ظٹظڈط¶ط§ظپ ط§ظ„ط±طµظٹط¯ ظ„ظ…ط­ظپط¸طھظƒ ظپظˆط± ط§ظ„طھط£ظƒظٹط¯ ظˆط³ظٹطµظ„ظƒ ط¥ط´ط¹ط§ط±.",
        reply_markup=HOME_KB,
    )


