@dp.callback_query(F.data == "client:orders")
async def my_orders(cb: types.CallbackQuery, state: FSMContext):
    await state.clear()
    async with get_db() as db:
        cur = await db.execute(
            "SELECT order_id, service_name, price, status, created_at FROM orders WHERE user_id = ? "
            "ORDER BY created_at DESC, rowid DESC LIMIT 20", (cb.from_user.id,)
        )
        rows = await cur.fetchall()
    if not rows:
        await safe_edit(cb, "ًں“¦ ظ„ط§ طھظˆط¬ط¯ ط·ظ„ط¨ط§طھ ط¨ط¹ط¯.", HOME_KB)
        return
    lines = ["ًں“¦ <b>ط¢ط®ط± ط·ظ„ط¨ط§طھظƒ</b> (ط­طھظ‰ 20):", "â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€"]
    for oid, name, price, status, created in rows:
        lines.append(f"{ORDER_STATUS_LABEL.get(status, status)} â€” {esc(name)} â€” <b>{price:,}</b> ظ„.ط³\n"
                     f"<code>{oid}</code> آ· {str(created)[:16]}")
    text = "\n".join(lines)
    if len(text) > 4000:
        text = text[:3990] + "â€¦"
    detail_rows = [[B(f"ًں”ژ {oid} â€” {name[:22]}", f"co:{oid}")] for oid, name, *_ in rows[:8]]
    await safe_edit(cb, text, KB(detail_rows + [[B("ًں”„ طھط­ط¯ظٹط«", "client:orders")], [B("ًںڈ  ط§ظ„ط±ط¦ظٹط³ظٹط©", "back_home")]]))


