# 11. ظ…ط­ط±ظƒ ط§ظ„ط´ط±ط§ط، ط§ظ„ظ…ظˆط­ط¯ (ط®طµظ… ظپظˆط±ظٹ ط°ط±ظٹ)
# =====================================================================
_recent_purchases: Dict[Tuple[int, str, str], float] = {}


async def process_wallet_purchase(event, user_id: int, dept: str, service: str, target: str, price: int, state: FSMContext,
                                  copy_value: Optional[str] = None, cost_syp: Optional[float] = None):
    await state.clear()

    # ط­ظ…ط§ظٹط© ظ…ظ† ط§ظ„ط¶ط؛ط· ط§ظ„ظ…ط²ط¯ظˆط¬ ط§ظ„ط³ط±ظٹط¹
    sig = (user_id, service, target)
    now = time.monotonic()
    for k in [k for k, t in _recent_purchases.items() if now - t > 5]:
        _recent_purchases.pop(k, None)
    if sig in _recent_purchases:
        if isinstance(event, types.CallbackQuery):
            await event.answer("âڈ³ ط¬ط§ط±ظچ ظ…ط¹ط§ظ„ط¬ط© ط·ظ„ط¨ظƒ...", show_alert=True)
        return
    _recent_purchases[sig] = now

    price = int(price)
    status, balance, ord_id = await WalletService.create_order(user_id, dept, service, target, price, cost_syp)

    if status == "NO_FUNDS":
        _recent_purchases.pop(sig, None)
        diff = price - balance
        text_no_bal = (
            f"â‌Œ <b>ط±طµظٹط¯ظƒ ط؛ظٹط± ظƒط§ظپظچ ظ„ط¥طھظ…ط§ظ… ط§ظ„ط´ط±ط§ط،!</b>\n"
            f"â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n"
            f"ًں“¦ ط§ظ„ط®ط¯ظ…ط©: <b>{esc(service)}</b>\n"
            f"ًں’µ ط§ظ„ط³ط¹ط± ط§ظ„ظ…ط·ظ„ظˆط¨: <b>{price:,} ظ„.ط³</b>\n"
            f"ًں’° ط±طµظٹط¯ظƒ ط§ظ„ط­ط§ظ„ظٹ: <b>{balance:,} ظ„.ط³</b>\n"
            f"âڑ ï¸ڈ ظٹظ†ظ‚طµظƒ: <b>{diff:,} ظ„.ط³</b>\n"
            f"â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n"
            f"ًں’، ظٹط±ط¬ظ‰ ط´ط­ظ† ظ…ط­ظپط¸طھظƒ ط£ظˆظ„ط§ظ‹ ظ„طھطھظ…ظƒظ† ظ…ظ† ط§ظ„ط´ط±ط§ط، ط¨ط¶ط؛ط·ط© ط²ط± ظˆط§ط­ط¯ط©."
        )
        await respond(event, text_no_bal, KB([[B("â‍• ط´ط­ظ† ط§ظ„ظ…ط­ظپط¸ط© ط§ظ„ط¢ظ†", "wallet:topup")], [B("ًں”™ ط§ظ„ط¹ظˆط¯ط© ظ„ظ„ط±ط¦ظٹط³ظٹط©", "back_home")]]))
        return
    if status != "OK":
        _recent_purchases.pop(sig, None)
        err = "âڑ ï¸ڈ ط­ط¯ط« ط®ط·ط£ ط£ط«ظ†ط§ط، ط¥طھظ…ط§ظ… ط§ظ„ط·ظ„ط¨ (ظ„ظ… ظٹظڈط®طµظ… ط£ظٹ ظ…ط¨ظ„ط؛)طŒ ظٹط±ط¬ظ‰ ط§ظ„ظ…ط­ط§ظˆظ„ط© ظ„ط§ط­ظ‚ط§ظ‹."
        if isinstance(event, types.CallbackQuery):
            await event.answer(err, show_alert=True)
        else:
            await event.reply(err)
        return

    group_id = GROUPS.get(dept, GROUPS["balance"])
    group_card = (
        f"âڑ، <b>ط·ظ„ط¨ ط¬ط¯ظٹط¯ ظ…ط¯ظپظˆط¹ ظ…ظ† ط§ظ„ظ…ط­ظپط¸ط© (ط¬ط§ظ‡ط² ظ„ظ„طھظ†ظپظٹط°):</b>\n"
        f"ًں†” ط±ظ‚ظ… ط§ظ„ط·ظ„ط¨: <code>{ord_id}</code>\n"
        f"ًں‘¤ ط§ظ„ط²ط¨ظˆظ†: {user_tag(event.from_user)} (<code>{user_id}</code>)\n"
        f"ًں”‘ UID: <code>{user_id}</code>\n"
        f"ًں“¦ ط§ظ„ط®ط¯ظ…ط©: <b>{esc(service)}</b>\n"
        f"ًںژ¯ ط§ظ„ط¨ظٹط§ظ†ط§طھ: <code>{esc(target)}</code>\n"
        f"ًں’° ط§ظ„ظ…ط¨ظ„ط؛ ط§ظ„ظ…ط®طµظˆظ…: <b>{price:,} ظ„.ط³</b>\n"
        + (f"ًں“‹ ظ„ظ„ظ†ط³ط®: <code>{esc(copy_value)}</code>\n" if copy_value else "")
        + f"\nًں’، ظ„ظ„ط±ط¯ ط¹ظ„ظ‰ ط§ظ„ط²ط¨ظˆظ†طŒ ظ‚ظ… ط¨ط¹ظ…ظ„ ط±ط¯ (Reply) ظ…ط¨ط§ط´ط± ط¹ظ„ظ‰ ظ‡ط°ظ‡ ط§ظ„ط±ط³ط§ظ„ط©."
    )
    kb_group = KB([[B("âœ… طھظ… ط§ظ„طھظ†ظپظٹط°", f"ord_act:done:{ord_id}"), B("â‌Œ ط¥ظ„ط؛ط§ط، ظˆط§ط³طھط±ط¬ط§ط¹", f"ord_act:ref:{ord_id}")]])
    await send_to_staff(group_id, group_card, kb_group)

    success_card = (
        f"âڈ³ <b>ط·ظ„ط¨ظƒ ظ‚ظٹط¯ ط§ظ„ظ…ط¹ط§ظ„ط¬ط©</b>\n"
        f"â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n"
        f"ًں†” ط±ظ‚ظ… ط§ظ„ط·ظ„ط¨: <code>{ord_id}</code>\n"
        f"ًں“¦ ط§ظ„ط®ط¯ظ…ط©: <b>{esc(service)}</b>\n"
        f"ًںژ¯ ط§ظ„ط¨ظٹط§ظ†ط§طھ: <code>{esc(target)}</code>\n"
        f"ًں’µ ط§ظ„ظ…ط¨ظ„ط؛ ط§ظ„ظ…ط®طµظˆظ…: <b>{price:,} ظ„.ط³</b>\n"
        f"ًں’° ط±طµظٹط¯ظƒ ط§ظ„ظ…طھط¨ظ‚ظٹ: <b>{balance:,} ظ„.ط³</b>\n"
        f"â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n"
        f"âœ… طھظ… ط§ظ„ط®طµظ… ظ…ظ† ظ…ط­ظپط¸طھظƒ ظˆطھط­ظˆظٹظ„ ط§ظ„ط·ظ„ط¨ ظ„ظپط±ظٹظ‚ ط§ظ„طھظ†ظپظٹط°طŒ ظˆط³ظٹطµظ„ظƒ ط¥ط´ط¹ط§ط± ظپظˆط± ط§ظ„ط§ظ†طھظ‡ط§ط،.\n"
        f"ًں“¦ طھط§ط¨ط¹ ط­ط§ظ„طھظ‡ ظ…ظ† آ«ط·ظ„ط¨ط§طھظٹآ» ظپظٹ ط§ظ„ظ‚ط§ط¦ظ…ط© ط§ظ„ط±ط¦ظٹط³ظٹط©."
    )
    await respond(event, success_card, HOME_KB)


