MARGIN_SECTIONS = {"balance": "ط§ظ„ط±طµظٹط¯ (ظˆط­ط¯ط§طھ ط³ظٹط±ظٹطھظ„/MTN)", "station": "ط§ظ„ظƒط§ط²ظٹط§طھ (ط¬ظ…ظ„ط©)", "invoice": "ط§ظ„ظپظˆط§طھظٹط±", "cash": "ط§ظ„ظƒط§ط´", "games": "ط§ظ„ط£ظ„ط¹ط§ط¨", "chat": "طھط·ط¨ظٹظ‚ط§طھ ط§ظ„ط´ط§طھ", "accounts": "ط§ظ„ط­ط³ط§ط¨ط§طھ ط§ظ„ط¬ط§ظ‡ط²ط©", "social": "ط§ظ„ط³ظˆط´ظٹط§ظ„ ظ…ظٹط¯ظٹط§", "numbers": "ط£ط±ظ‚ط§ظ… ط§ظ„طھظپط¹ظٹظ„"}  # ط£ظ‚ط³ط§ظ… ط£ط®ط±ظ‰ طھظڈط¶ط§ظپ ظ‡ظ†ط§ ظ„ط§ط­ظ‚ط§ظ‹


async def sell_price(cost_usd: Optional[float] = None, cost_syp: Optional[float] = None, section: str = "games") -> int:
    """ط³ط¹ط± ط§ظ„ط¨ظٹط¹ = ط§ظ„ط¬ظ…ظ„ط© أ— (1 + ظ†ط³ط¨ط© ط§ظ„ط±ط¨ط­)طŒ ظ…ط¹ طھظ‚ط±ظٹط¨ ظ„ط£ط¹ظ„ظ‰. ط§ظ„ط¯ظˆظ„ط§ط± ظٹظڈط­ظˆظژظ‘ظ„ ط¨ط³ط¹ط± ط§ظ„طµط±ظپ ط§ظ„ط­ط§ظ„ظٹ."""
    margin = await get_setting(f"margin_{section}")
    cost = cost_usd * await get_setting("dollar_rate") if cost_usd is not None else float(cost_syp or 0)
    return max(1, math.ceil(round(cost * (1 + margin / 100), 6)))


