    d = await state.get_data()
    if not d.get("cf_price") or not d.get("cf_service"):
        await state.clear()
        await safe_edit(cb, "âڑ ï¸ڈ ط§ظ†طھظ‡طھ طµظ„ط§ط­ظٹط© ظ‡ط°ظ‡ ط§ظ„ط®ط·ظˆط©. ظٹط±ط¬ظ‰ ط§ظ„ط¨ط¯ط، ظ…ظ† ط¬ط¯ظٹط¯:", HOME_KB)
        return
    px = d.get("cf_px")
