_admin_cache: Dict[Tuple[int, int], float] = {}


async def is_authorized(user_id: int, chat_id: int) -> bool:
    """ط§ظ„ظ…ط¯ظٹط±طŒ ط£ظˆ ظ…ظˆط¸ظپ ظ…ط¶ط§ظپ ظ…ظ† ط§ظ„ظ„ظˆط­ط©طŒ ط£ظˆ ظ…ط´ط±ظپ طھظ„ط؛ط±ط§ظ… ظپظٹ ظ…ط¬ظ…ظˆط¹ط© ط§ظ„ط¥ط¯ط§ط±ط© ظ†ظپط³ظ‡ط§."""
    if user_id == ADMIN_ID:
        return True
    if chat_id not in ALL_ADMIN_GROUPS:
        return False
    if await fetch_one("SELECT 1 AS x FROM staff WHERE user_id=?", (user_id,)):
        return True
    key = (chat_id, user_id)
    now = time.monotonic()
    if _admin_cache.get(key, 0) > now:
        return True
    try:
        m = await bot.get_chat_member(chat_id, user_id)
        if m.status in ("administrator", "creator"):
            _admin_cache[key] = now + 300
            return True
    except Exception as e:
        log.warning("get_chat_member failed: %s", e)
    return False


async def staff_guard(cb: types.CallbackQuery) -> bool:
    chat_id = cb.message.chat.id if isinstance(cb.message, types.Message) else 0
    if await is_authorized(cb.from_user.id, chat_id):
        return True
    await cb.answer("â›” ظ„ظٹط³طھ ظ„ط¯ظٹظƒ طµظ„ط§ط­ظٹط©. ظٹط¬ط¨ ط£ظ† طھظƒظˆظ† ظ…ط´ط±ظپط§ظ‹ ظپظٹ ط§ظ„ظ…ط¬ظ…ظˆط¹ط© ط£ظˆ ظ…ط¶ط§ظپط§ظ‹ ظ„ظ‚ط§ط¦ظ…ط© ط§ظ„ظ…ظˆط¸ظپظٹظ†.", show_alert=True)
    return False


