    if action == "done":
        res = await WalletService.complete_order(ord_id)
        if not res:
            await cb.answer("âڑ ï¸ڈ ط§ظ„ط·ظ„ط¨ ط؛ظٹط± ظ…ظˆط¬ظˆط¯ ط£ظˆ طھظ… ط§طھط®ط§ط° ط¥ط¬ط±ط§ط، ط¹ظ„ظٹظ‡ ظ…ط³ط¨ظ‚ط§ظ‹!", show_alert=True)
            return
        cust_id, s_name = res
        try:
            await bot.send_message(cust_id, f"ًںژ‰ <b>طھظ… طھظ†ظپظٹط° ط·ظ„ط¨ظƒ ط¨ظ†ط¬ط§ط­!</b>\nًں“¦ ط§ظ„ط®ط¯ظ…ط©: <b>{esc(s_name)}</b>\nًں†” ط±ظ‚ظ… ط§ظ„ط·ظ„ط¨: <code>{ord_id}</code>")
        except Exception as e:
            log.warning("notify customer failed: %s", e)
        await log_staff(cb, "ORDER_DONE", ord_id, s_name)
