async def extract_customer_id(orig_text: str) -> Optional[int]:
    """ط§ط³طھط®ط±ط§ط¬ ط¢ظٹط¯ظٹ ط§ظ„ط²ط¨ظˆظ†: UID ط£ظˆظ„ط§ظ‹طŒ ط«ظ… ط³ط·ط± ط§ظ„ط²ط¨ظˆظ†طŒ ط«ظ… ط±ظ‚ظ… ط§ظ„ط·ظ„ط¨/ط§ظ„ط¯ظپط¹ط© ظ…ظ† ظ‚ط§ط¹ط¯ط© ط§ظ„ط¨ظٹط§ظ†ط§طھطŒ ط«ظ… ط£ظٹ ط±ظ‚ظ… ط¨ظٹظ† ظ‚ظˆط³ظٹظ†."""
    m = re.search(r"UID:\s*(\d{5,15})", orig_text)
    if m:
        return int(m.group(1))
    m = re.search(r"ط§ظ„ط²ط¨ظˆظ†:.*?\((\d{5,15})\)", orig_text)
    if m:
        return int(m.group(1))
    m = re.search(r"ط±ظ‚ظ… ط§ظ„ط·ظ„ط¨:\s*(\d{4,})", orig_text)
    if m:
        uid = await WalletService.user_by_reference(m.group(1))
        if uid:
            return uid
    m = re.search(r"\b((?:ORD|PAY)-[0-9A-Z]+-[0-9A-Z]+)\b", orig_text)
    if m:
        uid = await WalletService.user_by_reference(m.group(1))
        if uid:
            return uid
    m = re.search(r"\((\d{6,15})\)", orig_text)
    return int(m.group(1)) if m else None


@dp.message(F.reply_to_message, F.chat.id.in_(ALL_ADMIN_GROUPS))
async def admin_group_direct_reply(message: types.Message):
    replied = message.reply_to_message
    if not replied.from_user or replied.from_user.id != bot.id:
        return
    admin_text = message.text or message.caption
    if not admin_text or admin_text.startswith("/"):
        return

    orig_text = replied.text or replied.caption or ""
    cust_id = await extract_customer_id(orig_text)
    if not cust_id:
        await message.reply("âڑ ï¸ڈ طھط¹ط°ط± ط§ط³طھط®ط±ط§ط¬ ط¢ظٹط¯ظٹ ط§ظ„ط²ط¨ظˆظ† ظ…ظ† ط§ظ„ط±ط³ط§ظ„ط© ط§ظ„طھظٹ ط±ط¯ط¯طھ ط¹ظ„ظٹظ‡ط§.")
        return
    try:
        await bot.send_message(cust_id, f"ًں’¬ <b>ط¥ط´ط¹ط§ط± ظ…ظ† ط§ظ„ط¥ط¯ط§ط±ط© ط¨ط®طµظˆطµ ط·ظ„ط¨ظƒ:</b>\n\n{esc(admin_text)}")
        await message.reply("âœ… طھظ… طھط³ظ„ظٹظ… ط§ظ„ط±ط¯ ظ„ظ„ط¹ظ…ظٹظ„ ط¨ظ†ط¬ط§ط­.")
    except TelegramForbiddenError:
        await message.reply("âڑ ï¸ڈ طھط¹ط°ط± ط§ظ„ط¥ط±ط³ط§ظ„: ظ‚ط§ظ… ط§ظ„ط¹ظ…ظٹظ„ ط¨ط­ط¸ط± ط§ظ„ط¨ظˆطھ.")
    except TelegramRetryAfter as e:
        await asyncio.sleep(e.retry_after)
        try:
            await bot.send_message(cust_id, f"ًں’¬ <b>ط¥ط´ط¹ط§ط± ظ…ظ† ط§ظ„ط¥ط¯ط§ط±ط© ط¨ط®طµظˆطµ ط·ظ„ط¨ظƒ:</b>\n\n{esc(admin_text)}")
            await message.reply("âœ… طھظ… طھط³ظ„ظٹظ… ط§ظ„ط±ط¯ ظ„ظ„ط¹ظ…ظٹظ„ ط¨ظ†ط¬ط§ط­.")
        except Exception as e2:
            await message.reply(f"âڑ ï¸ڈ ظپط´ظ„ طھط³ظ„ظٹظ… ط§ظ„ط±ط³ط§ظ„ط©: {esc(str(e2))}")
    except Exception as e:
        await message.reply(f"âڑ ï¸ڈ ظپط´ظ„ طھط³ظ„ظٹظ… ط§ظ„ط±ط³ط§ظ„ط©: {esc(str(e))}")


