        kb = KB([[B("âœ… طµط±ظپ ط§ظ„ظ…ظƒط§ظپط£ط©", f"ref_rw:ok:{reward_id}"), B("â‌Œ ط±ظپط¶", f"ref_rw:no:{reward_id}")]])
