    if not row:
        return None, None
    profit = f"\nًں“ˆ ط§ظ„ط±ط¨ط­: <b>{row['price'] - row['cost']:,.0f} ظ„.ط³</b> (ط§ظ„طھظƒظ„ظپط© {row['cost']:,.0f})" if row["cost"] is not None else ""
    text = (
        f"ًں“¦ <b>ط¨ط·ط§ظ‚ط© ط·ظ„ط¨</b>\n"
        f"ًں†” ط±ظ‚ظ… ط§ظ„ط·ظ„ط¨: <code>{oid}</code>\n"
        f"ًں‘¤ ط§ظ„ط²ط¨ظˆظ†: <code>{row['user_id']}</code>\n"
        f"ًں”‘ UID: <code>{row['user_id']}</code>\n"
        f"ًں—‚ ط§ظ„ظ‚ط³ظ…: {esc(row['department'])}\n"
        f"ًں“¦ ط§ظ„ط®ط¯ظ…ط©: <b>{esc(row['service_name'])}</b>\n"
        f"ًںژ¯ ط§ظ„ط¨ظٹط§ظ†ط§طھ: <code>{esc(row['target_data'])}</code>\n"
        f"ًں’° ط§ظ„ط³ط¹ط±: <b>{row['price']:,} ظ„.ط³</b>{profit}\n"
        f"ًں“Œ ط§ظ„ط­ط§ظ„ط©: <b>{row['status']}</b>\n"
        f"ًں•’ {row['created_at']}"
        + (f"\nًں“‌ ط³ط¨ط¨ ط§ظ„ط¥ظ„ط؛ط§ط،: {esc(row['cancel_reason'])}" if row["cancel_reason"] else "")
    )
    kb = KB([[B("âœ… طھظ… ط§ظ„طھظ†ظپظٹط°", f"ord_act:done:{oid}"), B("â‌Œ ط¥ظ„ط؛ط§ط، ظˆط§ط³طھط±ط¬ط§ط¹", f"ord_act:ref:{oid}")]]) if row["status"] == "PROCESSING" else None
    return text, kb


