# ---------------- ط¥ط¯ط§ط±ط© ط§ظ„ظ…ط³طھط®ط¯ظ…ظٹظ† ----------------
async def user_card(uid: int):
    async with get_db() as db:
        cur = await db.execute(f"SELECT {USER_COLS}, created_at FROM users WHERE user_id=?", (uid,))
        u = await cur.fetchone()
        if not u:
            return None, None
        c = await (await db.execute("SELECT COUNT(*), COALESCE(SUM(status='PROCESSING'),0) FROM orders WHERE user_id=?", (uid,))).fetchone()
        dep = (await (await db.execute("SELECT SUM(amount) FROM payments WHERE user_id=? AND status='ACCEPTED'", (uid,))).fetchone())[0] or 0
        led = await (await db.execute(
            "SELECT type, amount, balance_after, created_at FROM wallet_ledger WHERE user_id=? ORDER BY ledger_id DESC LIMIT 5", (uid,)
        )).fetchall()
    uname = f"@{esc(u[1])}" if u[1] else "â€”"
    lines = "\n".join(f"â€¢ {t} | {a:+,} â†’ {b:,} | {d}" for t, a, b, d in led) or "â€”"
    text = (
        f"ًں‘¤ <b>ط¨ط·ط§ظ‚ط© ظ…ط³طھط®ط¯ظ…</b>\n"
        f"â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n"
        f"ًں†” <code>{u[0]}</code> | {uname}\n"
        f"ًں“› ط§ظ„ط§ط³ظ…: {esc(u[6] or 'â€”')}\n"
        f"ًں’° ط§ظ„ط±طµظٹط¯: <b>{u[2]:,} ظ„.ط³</b>\n"
        f"â­گ VIP: {'ظ†ط¹ظ…' if u[3] else 'ظ„ط§'} | ًںڑ« ظ…ط­ط¸ظˆط±: {'ظ†ط¹ظ…' if u[4] else 'ظ„ط§'} | ط§ظ„ط±طھط¨ط©: {u[5]}\n"
        f"ًں“¦ ط§ظ„ط·ظ„ط¨ط§طھ: {c[0]} (ظ…ط¹ظ„ظ‚: {c[1]}) | ًں’³ ط¥ط¬ظ…ط§ظ„ظٹ ط§ظ„ط¥ظٹط¯ط§ط¹ط§طھ: {dep:,}\n"
        f"ًں•’ ط§ظ†ط¶ظ…: {u[7]}\n"
        f"â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€\n"
        f"ًں§¾ <b>ط¢ط®ط± ط§ظ„ط­ط±ظƒط§طھ:</b>\n{lines}"
    )
    kb = KB([
        [B("â‍• ط¥ط¶ط§ظپط© ط±طµظٹط¯", f"adm:ub:add:{uid}"), B("â‍– ط³ط­ط¨ ط±طµظٹط¯", f"adm:ub:sub:{uid}")],
        [B("âœ… ظپظƒ ط§ظ„ط­ط¸ط±" if u[4] else "ًںڑ« ط­ط¸ط±", f"adm:ban:{uid}"), B("âœ‰ï¸ڈ ظ…ط±ط§ط³ظ„ط©", f"adm:msg:{uid}")],
        [B("ًں”™ ظ„ظˆط­ط© ط§ظ„طھط­ظƒظ…", "adm:home")],
    ])
    return text, kb


