# ---------------- ط¥ط¯ط§ط±ط© ط§ظ„ط®ط¯ظ…ط§طھ (ط§ظ„ظƒطھط§ظ„ظˆط¬) ----------------
def cur_sym(cur: str) -> str:
    return "$" if cur == "USD" else "ظ„.ط³"


def parse_price(s: str):
    """ط±ظ‚ظ… ظ…ط¹ $ = ط¯ظˆظ„ط§ط±طŒ ظˆط¨ط¯ظˆظ†ظ‡ط§ = ظ„ظٹط±ط© ط³ظˆط±ظٹط©. ظٹط±ط¬ط¹ (ط§ظ„ط³ط¹ط±, ط§ظ„ط¹ظ…ظ„ط©) ط£ظˆ None."""
    s = s.strip().replace("ظ«", ".").replace("طŒ", ",")
    usd = "$" in s
    s = s.replace("$", "").replace(",", "").strip()
    try:
        v = float(s)
    except ValueError:
        return None
    if v != v or v <= 0 or v > 1e9:
        return None
    return v, ("USD" if usd else "SYP")


def parse_pack_lines(text: str):
    """ظƒظ„ ط³ط·ط±: ط§ظ„ط§ط³ظ… = ط§ظ„ط³ط¹ط±. ظٹط±ط¬ط¹ (ط§ظ„ظ‚ط§ط¦ظ…ط©, ط§ظ„ط£ط³ط·ط± ط§ظ„ط®ط§ط·ط¦ط©)."""
    good, bad = [], []
    for line in text.splitlines():
        line = line.strip().lstrip("*â€¢-â€“ ").strip()
        if not line:
            continue
        label, sep, price = line.rpartition("=")
        pr = parse_price(price) if sep else None
        label = label.strip()
        if not label or len(label) > 80 or pr is None:
            bad.append(line)
        else:
            good.append((label, pr[0], pr[1]))
    return good, bad


async def service_card(sid: int):
    s = await get_service(sid)
    if not s:
        return None, None
    packs = await fetch_all("SELECT * FROM catalog_packs WHERE service_id=? ORDER BY id", (sid,))
    sec = SECTIONS[s["section"]]
    plat = f" | ط§ظ„ظ…ظ†طµط©: {SOCIAL_PLATFORMS[s['platform']][1]}" if s["platform"] in SOCIAL_PLATFORMS else ""
    lines = [
        f"ًں—‚ <b>{esc(s['name'])}</b>",
        f"ط§ظ„ظ‚ط³ظ…: {sec['label']}{plat}",
        f"ط§ظ„ط­ط§ظ„ط©: {'ًں™ˆ ظ…ط®ظپظٹط© ط¹ظ† ط§ظ„ط²ط¨ط§ط¦ظ†' if s['is_hidden'] else 'ًں‘پ ط¸ط§ظ‡ط±ط©'}",
        f"ط§ظ„ظ†ظˆط¹: {'ط¨ط§ظ„ظƒظ…ظٹط©' if s['kind'] == 'qty' else 'ظپط¦ط§طھ ط«ط§ط¨طھط©'}",
        f"ظ†طµ ط§ظ„ط·ظ„ط¨: {esc(s['ask'] or 'â€”')}",
    ]
    if s["notes"]:
        lines.append(f"ط§ظ„ظ…ظ„ط§ط­ط¸ط§طھ: {esc(s['notes'])}")
    if s["kind"] == "qty":
        lines.append(f"ًں“‰ ط§ظ„ط­ط¯ ط§ظ„ط£ط¯ظ†ظ‰: {s['min_qty']:,} = {fmt_num(s['min_price'])} ظ„.ط³ | ًں“ˆ ط§ظ„ظˆط­ط¯ط© ط¨ط¹ط¯ظ‡: {fmt_num(s['unit_price'])} ظ„.ط³")
    else:
        lines.append(f"ط¹ط¯ط¯ ط§ظ„ظپط¦ط§طھ: {len(packs)}" + ("  âڑ ï¸ڈ ظ„ط§ ظپط¦ط§طھ: ط§ظ„ط®ط¯ظ…ط© ظ„ط§ طھط¸ظ‡ط± ظ„ظ„ط²ط¨ط§ط¦ظ†" if not packs else ""))
    if s["tok_min"]:
        lines.append(f"ًںھ™ طھظˆظƒظ†ط²: ط§ظ„ط­ط¯ ط§ظ„ط£ط¯ظ†ظ‰ {s['tok_min']:,} | ط³ط¹ط± ط§ظ„طھظˆظƒظ† {fmt_num(s['tok_unit'])} ظ„.ط³")
    rows = []
    for p in packs:
        mark = "ًں™ˆ " if p["is_hidden"] else ""
        rows.append([B(f"{mark}{p['label']} â€” {fmt_num(p['price'])}{cur_sym(p['cur'])}", f"adm:pk:{p['id']}")])
    if s["kind"] == "packs":
        rows.append([B("â‍• ط¥ط¶ط§ظپط© ظپط¦ط§طھ", f"adm:pa:{sid}")])
    else:
        rows.append([B("âœڈï¸ڈ ط§ظ„ط­ط¯ ط§ظ„ط£ط¯ظ†ظ‰ ظˆط§ظ„ط£ط³ط¹ط§ط±", f"adm:ed:s:{sid}:qty")])
    if s["tok_min"]:
        rows.append([B("ًںھ™ طھط¹ط¯ظٹظ„ ط§ظ„طھظˆظƒظ†ط²", f"adm:ed:s:{sid}:tok")])
    rows.append([B("âœڈï¸ڈ ط§ظ„ط§ط³ظ…", f"adm:ed:s:{sid}:name"), B("âœڈï¸ڈ ظ†طµ ط§ظ„ط·ظ„ط¨", f"adm:ed:s:{sid}:ask")])
    rows.append([B("âœڈï¸ڈ ط§ظ„ظ…ظ„ط§ط­ط¸ط§طھ", f"adm:ed:s:{sid}:notes")])
    rows.append([B("ًں”’ ط¨ظٹط§ظ†ط§طھ ط­ط³ط§ط³ط©: ظ…ظپط¹ظ‘ظ„" if s.get("sensitive") else "ًں”“ ط¨ظٹط§ظ†ط§طھ ط­ط³ط§ط³ط©: ظ…ط¹ط·ظ‘ظ„", f"adm:sens:{sid}")])
    rows.append([B("ًں‘پ ط¥ط¸ظ‡ط§ط±" if s["is_hidden"] else "ًں™ˆ ط¥ط®ظپط§ط،", f"adm:hd:s:{sid}"), B("ًں—‘ ط­ط°ظپ ط§ظ„ط®ط¯ظ…ط©", f"adm:dl:s:{sid}")])
    rows.append([B("ًں”™ ط§ظ„ظ‚ط³ظ…", f"adm:cs:{s['section']}:0")])
    return "\n".join(lines), KB(rows)


