@dp.callback_query(F.data.startswith("adm:cs:"))
async def adm_cat_section(cb: types.CallbackQuery, state: FSMContext):
    if not is_admin_cb(cb):
        return
    await state.clear()
    _, _, section, page_s = cb.data.split(":")
    if section not in SECTIONS:
        return
    items = await fetch_all(
        "SELECT * FROM catalog_services WHERE section=? ORDER BY " + ("lower(name)" if section == "chat" else "id"), (section,)
    )
    per = 8
    total = max(1, (len(items) + per - 1) // per)
    page = min(max(int(page_s), 0), total - 1)
    chunk = items[page * per:(page + 1) * per]
    rows = [[B("â‍• ط¥ط¶ط§ظپط© ط®ط¯ظ…ط© ط¬ط¯ظٹط¯ط©", f"adm:csa:{section}")]]
    rows += rows_of([B(("ًں™ˆ " if s["is_hidden"] else "") + s["name"], f"adm:sv:{s['id']}") for s in chunk], 1)
    nav = []
    if page > 0:
        nav.append(B("â¬…ï¸ڈ ط§ظ„ط³ط§ط¨ظ‚", f"adm:cs:{section}:{page - 1}"))
    if page < total - 1:
        nav.append(B("ط§ظ„طھط§ظ„ظٹ â‍،ï¸ڈ", f"adm:cs:{section}:{page + 1}"))
    if nav:
        rows.append(nav)
    rows.append([B("ًں”™ ط§ظ„ط£ظ‚ط³ط§ظ…", "adm:cat")])
    meta = SECTIONS[section]
    await safe_edit(cb, f"{meta['emoji']} <b>{meta['label']}</b> â€” {len(items)} ط®ط¯ظ…ط© (طµظپط­ط© {page + 1} ظ…ظ† {total})", KB(rows))


