@dp.message(AdminActions.set_channel)
async def adm_fsub_set_rec(message: types.Message, state: FSMContext):
    if message.from_user.id != ADMIN_ID:
        return
    parts = txt(message).split()
    if not parts:
        await message.reply("âڑ ï¸ڈ ط£ط±ط³ظ„ ظ…ط¹ط±ظ‘ظپ ط§ظ„ظ‚ظ†ط§ط©:")
        return
    raw = parts[0]
    link = parts[1] if len(parts) > 1 else ""
    m = re.match(r"^(?:https?://)?t\.me/([A-Za-z0-9_]{4,})/?$", raw)
    if m:
        raw = "@" + m.group(1)
    elif re.match(r"^[A-Za-z0-9_]{4,}$", raw):
        raw = "@" + raw
    ref = int(raw) if raw.lstrip("-").isdigit() else raw
    try:
        chat = await bot.get_chat(ref)
    except Exception as e:
        await message.reply(f"â‌Œ طھط¹ط°ط± ط§ظ„ظˆطµظˆظ„ ظ„ظ„ظ‚ظ†ط§ط©: {esc(str(e))}\nطھط£ظƒط¯ ظ…ظ† ط§ظ„ظ…ط¹ط±ظپ ظˆط£ظ† ط§ظ„ط¨ظˆطھ ظ…ط¶ط§ظپ ظپظٹظ‡ط§طŒ ط«ظ… ط£ط¹ط¯ ط§ظ„ظ…ط­ط§ظˆظ„ط©:")
        return
    try:
        me = await bot.get_chat_member(chat.id, bot.id)
        bot_is_admin = me.status in ("administrator", "creator")
    except Exception:
        bot_is_admin = False
    if not link:
        if chat.username:
            link = f"https://t.me/{chat.username}"
        else:
            try:
                link = await bot.export_chat_invite_link(chat.id)
            except Exception:
                link = ""
    await set_config("force_channel", str(chat.id))
    await set_config("force_title", chat.title or "")
    await set_config("force_link", link)
    _sub_cache.clear()
    await state.clear()
    warn = "" if bot_is_admin else "\n\nâڑ ï¸ڈ <b>ط§ظ„ط¨ظˆطھ ظ„ظٹط³ ظ…ط´ط±ظپط§ظ‹ ظپظٹ ط§ظ„ظ‚ظ†ط§ط©</b>طŒ ظ„ظ† ظٹط¹ظ…ظ„ ط§ظ„ظپط­طµ ظ‚ط¨ظ„ ط±ظپط¹ظ‡ ظƒظ…ط´ط±ظپ."
    if not link:
        warn += "\nâڑ ï¸ڈ ظ„ط§ ظٹظˆط¬ط¯ ط±ط§ط¨ط· ط¯ط¹ظˆط©طŒ ط£ط±ط³ظ„ ط§ظ„ط¥ط¹ط¯ط§ط¯ ظ…ط¬ط¯ط¯ط§ظ‹ ظ…ط¹ ط§ظ„ط±ط§ط¨ط· ط¨ط¹ط¯ ط§ظ„ط¢ظٹط¯ظٹ."
    await message.reply(f"âœ… طھظ… طھظپط¹ظٹظ„ ط§ظ„ط§ط´طھط±ط§ظƒ ط§ظ„ط¥ط¬ط¨ط§ط±ظٹ ط¹ظ„ظ‰ <b>{esc(chat.title or str(chat.id))}</b>.{warn}")


