@dp.message(AdminActions.broadcast_msg)
async def adm_broadcast_rec(message: types.Message, state: FSMContext):
    if message.from_user.id != ADMIN_ID:
        return
    if not txt(message):
        await message.reply("âڑ ï¸ڈ ط£ط±ط³ظ„ ظ†طµط§ظ‹ ظ„ظ„ط¥ط°ط§ط¹ط©:")
        return
    body = f"ًں“¢ <b>ط¥ط´ط¹ط§ط± ط¹ط§ظ… ظ…ظ† ط§ظ„ط¥ط¯ط§ط±ط©:</b>\n\n{esc(txt(message))}"
    await state.clear()
    async with get_db() as db:
        cur = await db.execute("SELECT user_id FROM users WHERE is_banned = 0")
        users = await cur.fetchall()

    await message.reply(f"âڈ³ ط¬ط§ط±ظچ ط§ظ„ط¥ط±ط³ط§ظ„ ط¥ظ„ظ‰ {len(users)} ظ…ط³طھط®ط¯ظ…...")
    sent = failed = 0
    for (uid,) in users:
        for _ in range(2):
            try:
                await bot.send_message(uid, body)
                sent += 1
                break
            except TelegramRetryAfter as e:
                await asyncio.sleep(e.retry_after)
            except Exception:
                failed += 1
                break
        await asyncio.sleep(0.05)
    await message.answer(f"âœ… ط§ظƒطھظ…ظ„طھ ط§ظ„ط¥ط°ط§ط¹ط©! طھظ… ط§ظ„طھط³ظ„ظٹظ…: {sent} | ظپط´ظ„: {failed}")


