async def remind_stale():
    """طھط°ظƒظٹط± ظˆط§ط­ط¯ ظ„ظƒظ„ ط·ظ„ط¨/ط¥ظٹط¯ط§ط¹ طھط£ط®ط± ط¯ظˆظ† ط¥ط¬ط±ط§ط، (ظ„ط§ طھظƒط±ط§ط±)."""
    orders = await fetch_all(
        "SELECT order_id, department, service_name FROM orders WHERE status='PROCESSING' AND reminded=0 "
        f"AND created_at < datetime('now', '-{int(STALE_ORDER_MIN)} minutes') ORDER BY created_at LIMIT 60"
    )
    by_dept: Dict[str, list] = {}
    for o in orders:
        by_dept.setdefault(o["department"], []).append(o)
    for dept, items in by_dept.items():
        lines = "\n".join(f"â€¢ <code>{i['order_id']}</code> â€” {esc(i['service_name'])}" for i in items[:15])
        more = f"\nâ€¦ ظˆ{len(items) - 15} ط£ط®ط±ظ‰" if len(items) > 15 else ""
        await send_to_staff(
            GROUPS.get(dept, GROUPS["balance"]),
            f"âڈ° <b>طھط°ظƒظٹط±: {len(items)} ط·ظ„ط¨ ظ…ط¹ظ„ظ‘ظ‚ ظ…ظ†ط° ط£ظƒط«ط± ظ…ظ† {STALE_ORDER_MIN} ط¯ظ‚ظٹظ‚ط©</b>\n{lines}{more}",
        )
        for i in items:
            await exec_sql("UPDATE orders SET reminded=1 WHERE order_id=?", (i["order_id"],))
    pays = await fetch_all(
        "SELECT payment_id, user_id, amount FROM payments WHERE status='UNDER_REVIEW' AND reminded=0 "
        f"AND created_at < datetime('now', '-{int(STALE_PAYMENT_MIN)} minutes') ORDER BY created_at LIMIT 30"
    )
    if pays:
        lines = "\n".join(f"â€¢ <code>{x['payment_id']}</code> â€” {x['amount']:,} ظ„.ط³ â€” <code>{x['user_id']}</code>" for x in pays[:15])
        await send_to_staff(DEPOSIT_ADMIN_GROUP, f"âڈ° <b>طھط°ظƒظٹط±: {len(pays)} ط¥ظٹط¯ط§ط¹ ط¨ط§ظ†طھط¸ط§ط± ط§ظ„ظ…ط±ط§ط¬ط¹ط© ظ…ظ†ط° ط£ظƒط«ط± ظ…ظ† {STALE_PAYMENT_MIN} ط¯ظ‚ظٹظ‚ط©</b>\n{lines}")
        for x in pays:
            await exec_sql("UPDATE payments SET reminded=1 WHERE payment_id=?", (x["payment_id"],))


async def heartbeat():
    """ظ†ط¨ط¶ ظ„ظ…ط±ط§ظ‚ط¨ ط®ط§ط±ط¬ظٹ ظ…ط¬ط§ظ†ظٹ (ظ…ط«ظ„ healthchecks.io): ط¥ظ† طھظˆظ‚ظپ ط§ظ„ظ†ط¨ط¶ ظٹظ†ط¨ظ‘ظ‡ظƒ ط§ظ„ظ…ظˆظ‚ط¹."""
    if not HEALTHCHECK_URL:
        return
    try:
        import aiohttp
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=10)) as sess:
            async with sess.get(HEALTHCHECK_URL):
                pass
    except Exception as e:
        log.warning("heartbeat failed: %s", e)


async def scheduled_reconcile():
    bad = await reconcile_balances()
    if bad:
        lines = "\n".join(f"â€¢ <code>{b['user_id']}</code>: ط§ظ„ط±طµظٹط¯ {b['balance']:,} | ط§ظ„ط­ط±ظƒط§طھ {b['led']:,}" for b in bad[:15])
        try:
            await bot.send_message(ADMIN_ID, f"ًںڑ¨ <b>ط§ط®طھظ„ط§ظپ ظپظٹ ط£ط±طµط¯ط© {len(bad)} ط²ط¨ظˆظ†</b>\n{lines}")
        except Exception:
            pass


async def maybe_send_daily_report():
    local = time.gmtime(time.time() + TZ_OFFSET_HOURS * 3600)
    if local.tm_hour < REPORT_HOUR_LOCAL:
        return
    day = time.strftime("%Y-%m-%d", local)
    if await get_config("last_report_day") == day:
        return
    await set_config("last_report_day", day)
    try:
        await bot.send_message(ADMIN_ID, await build_report(0))
    except Exception as e:
        log.warning("daily report failed: %s", e)


async def ops_loop():
    tick = 0
    await asyncio.sleep(30)
    while True:
        try:
            await heartbeat()
            if tick % 5 == 0:
                await remind_stale()
            if tick and tick % 360 == 0:
                await scheduled_reconcile()
            await maybe_send_daily_report()
        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.error("ops loop error: %s", e)
        tick += 1
        await asyncio.sleep(60)


_ops_task: Optional[asyncio.Task] = None


def start_ops_task():
    global _ops_task
    _ops_task = asyncio.create_task(ops_loop())

    def _done(t: asyncio.Task):
        if t.cancelled():
            return
        log.error("ops loop stopped unexpectedly: %s â€” restarting in 30s", t.exception())
        asyncio.get_running_loop().call_later(30, start_ops_task)

    _ops_task.add_done_callback(_done)


# =====================================================================
# ط§ظ„ظ†ط³ط® ط§ظ„ط§ط­طھظٹط§ط·ظٹ ط§ظ„طھظ„ظ‚ط§ط¦ظٹ ط¥ظ„ظ‰ طھظ„ط؛ط±ط§ظ… (BACKUP_CHAT_ID)
# =====================================================================
_last_backup_mtime = 0.0


def _db_mtime() -> float:
    m = 0.0
    for suffix in ("", "-wal"):
        try:
            m = max(m, os.path.getmtime(DB_PATH + suffix))
        except OSError:
            pass
    return m


def _make_backup_file(dest_gz: str):
    """ظ†ط³ط®ط© ظ…طھط³ظ‚ط© ط¹ط¨ط± ظˆط§ط¬ظ‡ط© backup ظپظٹ SQLite (ط¢ظ…ظ†ط© ط£ط«ظ†ط§ط، ط§ظ„ظƒطھط§ط¨ط©) + ظپط­طµ ط³ظ„ط§ظ…ط© + ط¶ط؛ط·."""
    tmp = dest_gz + ".tmp.db"
    src = sqlite3.connect(DB_PATH, timeout=30)
    try:
        dst = sqlite3.connect(tmp)
        try:
            src.backup(dst)
            res = dst.execute("PRAGMA integrity_check").fetchone()[0]
        finally:
            dst.close()
    finally:
        src.close()
    if res != "ok":
        raise RuntimeError(f"integrity_check: {res}")
    with open(tmp, "rb") as fi, gzip.open(dest_gz, "wb", compresslevel=6) as fo:
        shutil.copyfileobj(fi, fo)
    os.remove(tmp)


def _encrypt_backup(path_gz: str) -> str:
    """طھط´ظپظٹط± ط§ظ„ظ†ط³ط®ط© ط¨ظƒظ„ظ…ط© ط³ط± (Fernet + PBKDF2). ظٹط±ظپط¹ ImportError ط¥ظ† ظ„ظ… طھظƒظ† ظ…ظƒطھط¨ط© cryptography ظ…ط«ط¨طھط©."""
    from cryptography.fernet import Fernet
    salt = os.urandom(16)
    key = base64.urlsafe_b64encode(hashlib.pbkdf2_hmac("sha256", BACKUP_PASSWORD.encode(), salt, 200_000, dklen=32))
    with open(path_gz, "rb") as f:
        token = Fernet(key).encrypt(f.read())
    out = path_gz + ".enc"
    with open(out, "wb") as f:
        f.write(b"SSB1" + salt + token)
    return out


_enc_warned = False


async def do_backup(reason: str) -> Tuple[bool, str]:
    global _last_backup_mtime
    if not BACKUP_CHAT_ID:
        return False, "BACKUP_CHAT_ID ط؛ظٹط± ظ…ط¶ط¨ظˆط·"
    stamp = time.strftime("%Y-%m-%d_%H%M", time.gmtime())
    path = os.path.join(tempfile.gettempdir(), f"syria_store_{stamp}.db.gz")
    mtime = _db_mtime()
    try:
        global _enc_warned
        await asyncio.to_thread(_make_backup_file, path)
        send_path, enc_note = path, "âڑ ï¸ڈ ط؛ظٹط± ظ…ط´ظپظ‘ط±ط©"
        if BACKUP_PASSWORD:
            try:
                send_path = await asyncio.to_thread(_encrypt_backup, path)
                enc_note = "ًں”’ ظ…ط´ظپظ‘ط±ط©"
            except ImportError:
                if not _enc_warned:
                    _enc_warned = True
                    try:
                        await bot.send_message(ADMIN_ID, "âڑ ï¸ڈ BACKUP_PASSWORD ظ…ط¶ط¨ظˆط· ظ„ظƒظ† ظ…ظƒطھط¨ط© <code>cryptography</code> ط؛ظٹط± ظ…ط«ط¨طھط©طŒ ظپط§ظ„ظ†ط³ط® طھظڈط±ط³ظ„ ط؛ظٹط± ظ…ط´ظپظ‘ط±ط©. ط£ط¶ظپظ‡ط§ ط¥ظ„ظ‰ requirements.txt.")
                    except Exception:
                        pass
        size = os.path.getsize(send_path)
        for attempt in range(3):
            try:
                await bot.send_document(
                    BACKUP_CHAT_ID, FSInputFile(send_path),
                    caption=f"ًں’¾ ظ†ط³ط®ط© ط§ط­طھظٹط§ط·ظٹط© {stamp} UTC ({reason}) â€” {size / 1024:.0f} KB â€” {enc_note}",
                )
                break
            except TelegramRetryAfter as e:
                if attempt == 2:
                    raise
                await asyncio.sleep(e.retry_after + 1)
        _last_backup_mtime = mtime
        return True, f"{size / 1024:.0f} KB"
    except Exception as e:
        log.error("backup failed: %s", e)
        return False, str(e)
    finally:
        for fp in (path, path + ".enc", path + ".tmp.db"):
            try:
                os.remove(fp)
            except OSError:
                pass


async def backup_loop():
    await asyncio.sleep(60)
    while True:
        try:
            if (not BACKUP_ONLY_IF_CHANGED) or _db_mtime() > _last_backup_mtime:
                ok, info = await do_backup("طھظ„ظ‚ط§ط¦ظٹ")
                if not ok:
                    try:
                        await bot.send_message(ADMIN_ID, f"âڑ ï¸ڈ ظپط´ظ„طھ ط§ظ„ظ†ط³ط®ط© ط§ظ„ط§ط­طھظٹط§ط·ظٹط© ط§ظ„طھظ„ظ‚ط§ط¦ظٹط©: {esc(info)}")
                    except Exception:
                        pass
        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.error("backup loop error: %s", e)
        await asyncio.sleep(max(5, BACKUP_INTERVAL_MIN) * 60)


@dp.callback_query(F.data == "adm:backup")
async def adm_backup_now(cb: types.CallbackQuery):
    if not is_admin_cb(cb):
        return
    await cb.answer("âڈ³ ط¬ط§ط±ظچ ط¥ظ†ط´ط§ط، ط§ظ„ظ†ط³ط®ط©...")
    ok, info = await do_backup("ظٹط¯ظˆظٹ")
    await cb.message.answer(f"âœ… ط£ظڈط±ط³ظ„طھ ط§ظ„ظ†ط³ط®ط© ط§ظ„ط§ط­طھظٹط§ط·ظٹط© ({info})." if ok else f"â‌Œ ظپط´ظ„طھ ط§ظ„ظ†ط³ط®ط©: {esc(info)}")


# =====================================================================
# 22. ط§ظ„ط¥ظ‚ظ„ط§ط¹
# =====================================================================
_backup_task: Optional[asyncio.Task] = None


def start_backup_task():
    """ظٹط´ط؛ظ‘ظ„ ط­ظ„ظ‚ط© ط§ظ„ظ†ط³ط® ط§ظ„ط§ط­طھظٹط§ط·ظٹ ظˆظٹط¹ظٹط¯ طھط´ط؛ظٹظ„ظ‡ط§ طھظ„ظ‚ط§ط¦ظٹط§ظ‹ ط¥ظ† طھظˆظ‚ظپطھ ظ„ط£ظٹ ط³ط¨ط¨."""
    global _backup_task
    _backup_task = asyncio.create_task(backup_loop())

    def _done(t: asyncio.Task):
        if t.cancelled():
            return
        log.error("backup loop stopped unexpectedly: %s â€” restarting in 30s", t.exception())
        asyncio.get_running_loop().call_later(30, start_backup_task)

    _backup_task.add_done_callback(_done)


async def main():
    await init_db()
    await bot.delete_webhook(drop_pending_updates=False)
    log.info("ًںڑ€ Syria Store Wallet-First System is running...")
    start_backup_task()
    start_ops_task()
    try:
        await dp.start_polling(bot, allowed_updates=dp.resolve_used_update_types())
    finally:
        if _backup_task:
            _backup_task.cancel()
        if _ops_task:
            _ops_task.cancel()
        await bot.session.close()


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except (KeyboardInterrupt, SystemExit):
        log.info("Bot stopped.")
